  payload:
    | { $case: "flowStartedOrContinued"; value: FlowStartedOrContinuedHistoryEvent }
    | { $case: "flowClosed"; value: FlowClosedHistoryEvent }
    | { $case: "stepWaitForCompleted"; value: StepWaitForCompletedEvent }
    | { $case: "stepWaitForFailed"; value: StepWaitForFailedEvent }
    | { $case: "stepExecuteCompleted"; value: StepExecuteCompletedEvent }
    | { $case: "stepExecuteFailed"; value: StepExecuteFailedEvent }
    | { $case: "rpcExecutionCompleted"; value: RpcExecutionCompletedEvent }
    | { $case: "channelExternalPublish"; value: ChannelExternalPublishEvent }
    | { $case: "stepWaitForPending"; value: StepMethodPendingEvent }
    | { $case: "stepExecutePending"; value: StepMethodPendingEvent }
